uint base = thread_position_in_grid.x * 8u;
const uint N = rows * I;
if (base + 8u <= N) {
    auto gp = (const device half4*)(g + base);
    auto up = (const device half4*)(u + base);
    auto op = (device half4*)(out + base);
    float4 g0 = float4(gp[0]), g1 = float4(gp[1]);
    float4 u0 = float4(up[0]), u1 = float4(up[1]);
    float4 r0 = g0 * u0 / (1.0f + fast::exp(-g0));
    float4 r1 = g1 * u1 / (1.0f + fast::exp(-g1));
    op[0] = half4(r0);
    op[1] = half4(r1);
} else {
    for (uint k = base; k < N; ++k) {
        float gv = float(g[k]);
        out[k] = half(gv * float(u[k]) / (1.0f + fast::exp(-gv)));
    }
}
